patternCss:
.bds-pattern-query-list {
  --bds-pattern-page-max-width: 1160px;
  --bds-pattern-page-padding-x: 44px;
  --bds-pattern-page-padding-y: 50px;
  --bds-pattern-section-gap: 16px;
  --bds-pattern-header-gap: 8px;
  --bds-pattern-header-action-alignment: space-between;
  --bds-pattern-content-padding: 20px;
  --bds-pattern-content-radius: var(--bds-radius-md, 6px);
  --bds-pattern-filter-columns: 3;
  --bds-pattern-filter-row-gap: 12px;
  --bds-pattern-filter-column-gap: 12px;
  --bds-pattern-field-min-width: 220px;
  --bds-pattern-field-max-width: 320px;
  --bds-pattern-filter-padding: 14px;
  --bds-pattern-filter-bg: var(--bds-bg-surface-alt, transparent);
  --bds-pattern-filter-radius: var(--bds-radius-md, 6px);
  --bds-pattern-results-gap: 12px;
  --bds-pattern-results-padding: 16px;
  --bds-pattern-results-bg: var(--bds-bg-surface, transparent);
  --bds-pattern-results-header-alignment: space-between;
  --bds-pattern-pagination-alignment: end;
  --bds-pattern-pagination-gap: 12px;
  --bds-pattern-table-min-width: 720px;
  --bds-pattern-action-alignment: start;
  --bds-pattern-actions-wrap: nowrap;
  --bds-pattern-compact-actions-full: 1;
  --bds-pattern-compact-pagination-wrap: wrap;
}

@media (max-width: 1050px) {
  .bds-pattern-query-list {
    --bds-pattern-filter-columns: 2;
    --bds-pattern-actions-wrap: wrap;
    --bds-pattern-page-max-width: none;
  }
}

@media (max-width: 620px) {
  .bds-pattern-query-list {
    --bds-pattern-filter-columns: 1;
    --bds-pattern-table-min-width: 560px;
    --bds-pattern-pagination-alignment: end;
  }
}
